  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div class="page-shell">
      <header>
        <p class="eyebrow" aria-hidden="true">Cat care basics</p>
      </header>
      <main id="main-content">
        <h1>Cat FAQ</h1>
        <p class="intro">
          Quick answers to common questions about feline habits, comfort,
          and care. Select a question to expand its answer.
        </p>
        <section class="faq-card" aria-label="Cat questions and answers">
          <div class="example">
            <button
              class="question"
              type="button"
              aria-expanded="false"
              aria-controls="faq-answer-0"
            >
              <span>Why do cats purr?</span>
              <span class="question-icon" aria-hidden="true">+</span>
            </button>
            <div class="details" id="faq-answer-0" hidden>
              <p>
                Cats often purr when they feel relaxed or bonded, but purring
                can also be self-soothing. Context matters: a cat stretched
                beside you is probably content, while a hiding cat may need
                quiet and space.
              </p>
            </div>
          </div>

          <div class="example">
            <button
              class="question"
              type="button"
              aria-expanded="false"
              aria-controls="faq-answer-1"
            >
              <span>How much sleep do cats need?</span>
              <span class="question-icon" aria-hidden="true">+</span>
            </button>
            <div class="details" id="faq-answer-1" hidden>
              <p>
                Most adult cats sleep 12 to 16 hours a day, and kittens or
                seniors may sleep even more. Their sleep comes in many short
                sessions because cats are naturally crepuscular, meaning they
                are most active around dawn and dusk.
              </p>
            </div>
          </div>

          <div class="example">
            <button
              class="question"
              type="button"
              aria-expanded="false"
              aria-controls="faq-answer-2"
            >
              <span>Why does my cat knead blankets?</span>
              <span class="question-icon" aria-hidden="true">+</span>
            </button>
            <div class="details" id="faq-answer-2" hidden>
              <p>
                Kneading is a comforting behavior that begins when kittens
                nurse. Many adult cats keep doing it when they feel safe, cozy,
                or ready to settle into a favorite resting spot.
              </p>
            </div>
          </div>

          <div class="example">
            <button
              class="question"
              type="button"
              aria-expanded="false"
              aria-controls="faq-answer-3"
            >
              <span>Do indoor cats need enrichment?</span>
              <span class="question-icon" aria-hidden="true">+</span>
            </button>
            <div class="details" id="faq-answer-3" hidden>
              <p>
                Yes. Indoor cats benefit from daily play, scratching surfaces,
                window views, climbing spaces, puzzle feeders, and predictable
                routines. Enrichment helps reduce boredom and supports healthy
                movement.
              </p>
            </div>
          </div>

          <div class="example">
            <button
              class="question"
              type="button"
              aria-expanded="false"
              aria-controls="faq-answer-4"
            >
              <span>How should I introduce a new cat?</span>
              <span class="question-icon" aria-hidden="true">+</span>
            </button>
            <div class="details" id="faq-answer-4" hidden>
              <p>
                Start slowly with separate spaces, scent swapping, and short
                supervised meetings. Let the cats set the pace, reward calm
                behavior, and avoid forcing close contact before both cats are
                comfortable.
              </p>
            </div>
          </div>
        </section>
      </main>
      <footer>
        <p>For urgent health changes, contact a licensed veterinarian.</p>
      </footer>
    </div>

    <script type="module">
      const FAQItem = ({ node }) => {
        const button = node.querySelector(".question");
        const details = node.querySelector(".details");

        const setExpanded = (isExpanded) => {
          button.setAttribute("aria-expanded", String(isExpanded));
          details.hidden = !isExpanded;
        };

        return {
          mount() {
            setExpanded(false);
            button.addEventListener("click", () => {
              const isExpanded = button.getAttribute("aria-expanded") === "true";
              setExpanded(!isExpanded);
            });
          }
        };
      };

      const FAQPage = ({ root }) => {
        return {
          mount() {
            root
              .querySelectorAll(".example")
              .forEach((node) => FAQItem({ node }).mount());
          }
        }
      };

      FAQPage({ root: document }).mount();
    </script>
  </body>
